package main

import (
	"context"
	"crypto/rand"
	"encoding/hex"
	"fmt"
	"net/http"
	"time"
)

type ctxKey string

const reqIDKey ctxKey = "reqID"

// RequestID middleware attaches a unique ID to the request context.
func RequestID(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		b := make([]byte, 8)
		_, _ = rand.Read(b)
		id := hex.EncodeToString(b)
		ctx := context.WithValue(r.Context(), reqIDKey, id)
		w.Header().Set("X-Request-ID", id)
		next.ServeHTTP(w, r.WithContext(ctx)) // carry the new context inward
	})
}

// handler respects cancellation via r.Context().
func handler(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	select {
	case <-time.After(2 * time.Second): // simulated downstream work
		id, _ := ctx.Value(reqIDKey).(string)
		fmt.Fprintf(w, "done (req %s)\n", id)
	case <-ctx.Done(): // client disconnected or timed out
		http.Error(w, "cancelled", 499)
	}
}

